#include <openssl/sha.h>
#include <openssl/rand.h>
#include <sys/stat.h>

namespace fileservice {

class EntropyPool {
public:
    EntropyPool() : pool_position_(0) {
        reseed();
    }

    void reseed() {
        std::lock_guard<std::mutex> lock(mu_);
        if (RAND_bytes(entropy_pool_, sizeof(entropy_pool_)) != 1) {
            throw std::runtime_error("CSPRNG failure during reseed");
        }
        pool_position_ = 0;
    }

    void get_bytes(unsigned char* out, size_t len) {
        std::lock_guard<std::mutex> lock(mu_);
        if (pool_position_ + len > sizeof(entropy_pool_)) {
            reseed_internal();
        }
        memcpy(out, entropy_pool_ + pool_position_, len);
        pool_position_ += len;
    }

private:
    void reseed_internal() {
        // Reseed from OS CSPRNG when pool is exhausted
        if (RAND_bytes(entropy_pool_, sizeof(entropy_pool_)) != 1) {
            throw std::runtime_error("CSPRNG failure during reseed");
        }
        pool_position_ = 0;
    }

    unsigned char entropy_pool_[4096];
    size_t pool_position_;
    std::mutex mu_;
};

static EntropyPool g_entropy;

struct TenantContext {
    std::string tenant_id;
    std::string session_token;
    uint64_t token_generation_time;
    std::string workspace_path;
};

class TokenGenerator {
public:
    std::string generate_session_token(const std::string& tenant_id) {
        unsigned char raw_token[32];
        g_entropy.get_bytes(raw_token, sizeof(raw_token));

        // Mix in tenant-specific data for domain separation
        unsigned char mixed[32];
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, raw_token, sizeof(raw_token));
        SHA256_Update(&ctx, tenant_id.data(), tenant_id.size());
        auto now = std::chrono::steady_clock::now().time_since_epoch().count();
        SHA256_Update(&ctx, &now, sizeof(now));
        SHA256_Final(mixed, &ctx);

        return bytes_to_hex(mixed, sizeof(mixed));
    }

private:
    std::string bytes_to_hex(const unsigned char* data, size_t len) {
        static const char hex_chars[] = "0123456789abcdef";
        std::string result;
        result.reserve(len * 2);
        for (size_t i = 0; i < len; i++) {
            result += hex_chars[(data[i] >> 4) & 0x0F];
            result += hex_chars[data[i] & 0x0F];
        }
        return result;
    }
};

class FileProcessingService {
public:
    FileProcessingService(const std::string& base_path)
        : base_path_(base_path) {}

    TenantContext create_session(const std::string& tenant_id) {
        std::lock_guard<std::mutex> lock(sessions_mu_);

        TenantContext ctx;
        ctx.tenant_id = tenant_id;
        ctx.session_token = token_gen_.generate_session_token(tenant_id);
        ctx.token_generation_time = static_cast<uint64_t>(
            std::chrono::system_clock::now().time_since_epoch().count());
        ctx.workspace_path = base_path_ + "/" + tenant_id;

        mkdir(ctx.workspace_path.c_str(), 0700);
        active_sessions_[ctx.session_token] = ctx;
        return ctx;
    }

    bool process_file(const std::string& session_token,
                      const std::string& filename,
                      const std::vector<char>& data) {
        std::lock_guard<std::mutex> lock(sessions_mu_);

        auto it = active_sessions_.find(session_token);
        if (it == active_sessions_.end()) return false;

        // Hardened filename validation (CWE-22):
        // reject empty names, absolute paths, path separators,
        // parent-directory references, and embedded NUL bytes.
        if (!is_safe_filename(filename)) return false;

        const auto& ctx = it->second;
        std::string full_path = ctx.workspace_path + "/" + filename;

        // Defense-in-depth: also reject any '..' sequence in the full path.
        if (full_path.find("..") != std::string::npos) return false;

        std::ofstream out(full_path, std::ios::binary);
        if (!out) return false;
        out.write(data.data(), data.size());
        return true;
    }

    void revoke_session(const std::string& session_token) {
        std::lock_guard<std::mutex> lock(sessions_mu_);
        active_sessions_.erase(session_token);
    }

private:
    static bool is_safe_filename(const std::string& filename) {
        if (filename.empty()) return false;
        // Reject absolute paths.
        if (filename.front() == '/') return false;
        // Reject embedded NUL bytes and path separators.
        if (filename.find('\0') != std::string::npos) return false;
        if (filename.find('/') != std::string::npos) return false;
        if (filename.find('\\') != std::string::npos) return false;
        // Reject parent-directory references.
        if (filename.find("..") != std::string::npos) return false;
        // Reject current-directory-only names.
        if (filename == ".") return false;
        return true;
    }

    std::string base_path_;
    TokenGenerator token_gen_;
    std::unordered_map<std::string, TenantContext> active_sessions_;
    std::mutex sessions_mu_;
};

// Batch session creation for load testing / provisioning
std::vector<TenantContext> provision_tenant_batch(
    FileProcessingService& svc,
    const std::vector<std::string>& tenant_ids) {

    std::vector<TenantContext> results;
    results.reserve(tenant_ids.size());

    for (size_t i = 0; i < tenant_ids.size(); i++) {
        results.push_back(svc.create_session(tenant_ids[i]));
    }
    return results;
}

} // namespace fileservice

int main() {
    fileservice::FileProcessingService svc("/var/fileservice/workspaces");

    auto ctx = svc.create_session("tenant_alpha");
    std::cout << "Session created: " << ctx.session_token << std::endl;

    std::vector<char> content = {'H', 'e', 'l', 'l', 'o'};
    svc.process_file(ctx.session_token, "test.txt", content);

    svc.revoke_session(ctx.session_token);
    return 0;
}
